"""Deterministic v9.2 member collapse on top of v9.1 REGION decisions.

V9.2 does not ask the model to reinterpret an image.  It collapses multiple
selected members of the same REGION family whenever the trusted R2 card does
not explicitly contain both ``left`` and ``right``.  A concrete entity ID is
retained for downstream schema compatibility, but an arbitrary representative
is explicitly marked unresolved.
"""

from __future__ import annotations

import hashlib
import json
import re
from collections import defaultdict
from typing import Any


def _opaque_family(payload: Any) -> str:
    rendered = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(rendered.encode("utf-8")).hexdigest()[:12]
    return f"collapse_family_{digest}"


def _region_number(entity_id: str) -> tuple[int, str]:
    match = re.search(r"(\d+)$", entity_id)
    return (int(match.group(1)) if match else 10**9, entity_id)


def _known_sides(values: Any) -> set[str]:
    raw = values if isinstance(values, (list, tuple, set)) else [values]
    return {str(value) for value in raw if str(value) in {"left", "right", "midline"}}


def _summary_none_signature(region: dict[str, Any]) -> str | None:
    """Identify exact non-location-equivalent summary-none members.

    ``neck_level`` and every clinical attribute remain in the signature.
    Only the schema ID and anatomic side label are removed.  Therefore regions
    at different neck levels or with different findings cannot be merged.
    """
    if str(region.get("focal_finding_summary", "none") or "none").strip().lower() != "none":
        return None
    comparable = {
        key: value
        for key, value in region.items()
        if key not in {"region_id", "anatomic_region"}
    }
    return json.dumps(comparable, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


class _UnionFind:
    def __init__(self, values: set[str]) -> None:
        self.parent = {value: value for value in values}

    def find(self, value: str) -> str:
        parent = self.parent[value]
        if parent != value:
            self.parent[value] = self.find(parent)
        return self.parent[value]

    def union(self, left: str, right: str) -> None:
        left_root = self.find(left)
        right_root = self.find(right)
        if left_root != right_root:
            self.parent[right_root] = left_root


def collapse_families(
    payload: dict[str, Any], report: dict[str, Any]
) -> tuple[dict[str, str], list[dict[str, Any]], dict[str, set[str]]]:
    """Return augmented family IDs, auditable groups, and entity lateralities.

    Existing v9.1 families remain authoritative.  The only augmentation is the
    previously accepted correction for summary-none regions: exact equality of
    every non-location field also makes left/right members one family.
    """
    regions = {
        str(region["region_id"]): region
        for region in report.get("regions", []) or []
    }
    eligible_ids = {
        str(entity_id)
        for family in payload["region_families"]
        for member in family["members"]
        for entity_id in member["entity_ids"]
    }
    union = _UnionFind(eligible_ids)
    laterality: dict[str, set[str]] = {}

    for family in payload["region_families"]:
        members = [
            (str(entity_id), member)
            for member in family["members"]
            for entity_id in member["entity_ids"]
        ]
        for entity_id, member in members:
            laterality[entity_id] = _known_sides(
                member["region_location"].get("member_laterality", [])
            )
        for (first, _), (other, _) in zip(members, members[1:]):
            union.union(first, other)

    exact_none_groups: dict[str, list[str]] = defaultdict(list)
    for entity_id in sorted(eligible_ids, key=_region_number):
        signature = _summary_none_signature(regions[entity_id])
        if signature is not None:
            exact_none_groups[signature].append(entity_id)
    for members in exact_none_groups.values():
        for entity_id in members[1:]:
            union.union(members[0], entity_id)

    grouped: dict[str, list[str]] = defaultdict(list)
    for entity_id in eligible_ids:
        grouped[union.find(entity_id)].append(entity_id)

    family_by_entity: dict[str, str] = {}
    groups: list[dict[str, Any]] = []
    for members in sorted(
        (sorted(values, key=_region_number) for values in grouped.values()),
        key=lambda values: _region_number(values[0]),
    ):
        family_id = _opaque_family(members)
        for entity_id in members:
            family_by_entity[entity_id] = family_id
        groups.append({
            "collapse_family_id": family_id,
            "entity_ids": members,
        })
    return family_by_entity, groups, laterality


def collapse_selected_regions_v92(
    *,
    payload: dict[str, Any],
    report: dict[str, Any],
    selected: dict[int, set[str]],
) -> tuple[dict[int, set[str]], list[dict[str, Any]], list[dict[str, Any]]]:
    """Apply the accepted v9.2 trigger and return final selections plus audit."""
    family_by_entity, groups, entity_laterality = collapse_families(payload, report)
    image_by_index = {
        int(image["image_index"]): image
        for image in payload["images"]
    }
    result = {int(index): set(values) for index, values in selected.items()}
    audits: list[dict[str, Any]] = []

    for image_index in sorted(result):
        image = image_by_index[image_index]
        image_sides = _known_sides(image["image_context"]["laterality"]["values"])
        trigger = not {"left", "right"} <= image_sides
        selected_by_family: dict[str, list[str]] = defaultdict(list)
        for entity_id in result[image_index]:
            if entity_id in family_by_entity:
                selected_by_family[family_by_entity[entity_id]].append(entity_id)

        for family_id, members in sorted(selected_by_family.items()):
            members = sorted(members, key=_region_number)
            if len(members) <= 1:
                continue
            if not trigger:
                audits.append({
                    "image_index": image_index,
                    "collapse_family_id": family_id,
                    "selected_members_before": members,
                    "selected_members_after": members,
                    "triggered": False,
                    "member_resolution": "bilateral_image_card_preserved",
                    "reason": "r2_laterality_contains_left_and_right",
                })
                continue

            matching = [
                entity_id
                for entity_id in members
                if entity_laterality.get(entity_id, set()) & image_sides
            ]
            pool = matching or members
            representative = min(pool, key=_region_number)
            removed = sorted(set(members) - {representative}, key=_region_number)
            result[image_index].difference_update(removed)
            uniquely_resolved = len(matching) == 1
            audits.append({
                "image_index": image_index,
                "collapse_family_id": family_id,
                "selected_members_before": members,
                "selected_members_after": [representative],
                "removed_members": removed,
                "triggered": True,
                "member_resolution": (
                    "resolved_by_r2_laterality"
                    if uniquely_resolved
                    else "unresolved_representative"
                ),
                "reason": (
                    "unique_member_matches_non_bilateral_r2_laterality"
                    if uniquely_resolved
                    else "minimum_region_id_represents_unresolved_family"
                ),
            })

    return result, audits, groups

"""Exact portable copies of the accepted confidence-.8 card prefilter helpers."""
KNOWN_NONE = {"", "none", "unknown", "unspecified", "not specified", "null"}


def known_values(values):
    raw = values if isinstance(values, (list, tuple, set)) else [values]
    return {str(v) for v in raw if str(v or "").strip().lower() not in KNOWN_NONE}


def axis_values(axis):
    return known_values(axis.get("values", [axis.get("value", "unknown")]))


def trusted(axis):
    return (float(axis.get("confidence", 0)) >= .80
            and not bool(axis.get("needs_review", True)) and bool(axis_values(axis)))


def compare_axis(axis, candidates):
    if not trusted(axis) or not candidates:
        return "unknown"
    return "match" if not axis_values(axis).isdisjoint(candidates) else "conflict"


def decision(card, candidate):
    conditions = candidate["conditions"]
    comparisons = {"laterality": compare_axis(card["laterality"], known_values(conditions["laterality"])),
                   "anatomy": compare_axis(card["anatomic_region"], known_values(conditions["anatomy"]))}
    state = ("reject" if "conflict" in comparisons.values() else
             "accept" if all(v == "match" for v in comparisons.values()) else "unresolved")
    return state, comparisons

"""Boolean-evidence ranked, complete Instance decisions; never emit unresolved.

The inventory determines capacity, not a requirement to fabricate a match.
Only ties after all observable evidence use stable source IDs, explicitly
recorded as forced decisions rather than established clinical identities.
"""
import re

from .instance_round2_target_contrast import LOCATION_FIELDS, validated_context

RANK_ORDER = (
    "anatomic_region_yes",
    "differing_attribute_yes_count",
    "laterality_yes",
    "location_detail_or_neck_level_yes_count",
    "common_attribute_yes_count",
)


def natural_id(value):
    return tuple((1, int(part)) if part.isdigit() else (0, part)
                 for part in re.split(r"(\d+)", str(value)))


def candidate_order(candidate):
    # Opaque hashes and list order are not tie-breaks.
    return tuple(sorted((natural_id(e) for e in candidate["entity_ids"])))


def pair_rank(image, pair):
    checks = {c["field"]: c["answer"] for c in pair["attribute_checks"]}
    return (
        int(pair["anatomic_region_match"] == "yes"),
        sum(checks[f] == "yes" for f in
            set(image["differing_attributes"]) |
            set(image.get("candidate_known_attributes", {}).get(pair["candidate_key"], {}))),
        int(pair["laterality_match"] == "yes"),
        sum(pair[f] == "yes" for f in ("location_detail_match", "neck_level_match")),
        sum(checks[f] == "yes" for f in image["common_attributes"]),
    )


def finalize_ranked(payload, output, max_nodes=200000, external_inventory=None):
    output, targets, images, relations, pairs, renamed = validated_context(payload, output, external_inventory=external_inventory)
    candidates = {c["candidate_key"]: c for c in payload["instance_candidates"]}
    options, ranks, edge_audit = {}, {}, []
    for (i, t, c), pair in pairs.items():
        answers = [pair[f] for f in LOCATION_FIELDS] + [a["answer"] for a in pair["attribute_checks"]]
        if "no" in answers:
            reason = "explicit_location_or_attribute_conflict"
        elif "yes" not in answers:
            reason = "no_positive_attribute_match"
        else:
            reason = "eligible"
            options.setdefault((i, t), []).append(c)
            ranks[(i, t, c)] = pair_rank(images[i], pair)
        edge_audit.append({"image_index": i, "target_id": t, "candidate_key": c,
                           "status": reason, "rank": list(ranks.get((i, t, c), ()))})

    for values in options.values():
        values.sort(key=lambda c: candidate_order(candidates[c]))
    target_keys = [(i, t) for i in (1, 2) for t in sorted(targets[i])]
    selected_edges, used = [], {}
    best_objective, best_edges, best_signature = None, [], None
    optimal_count, visited = 0, 0
    optimal_union, optimal_intersection = set(), set()
    optimal_edge_union = set()

    def signature(edges):
        # Source-ID tie-break, then image index and target ID. It is a total
        # order only for reproducibility, NOT additional visual evidence.
        return tuple(sorted((candidate_order(candidates[c]), i, t) for i, t, c in edges))

    def visit(position, rank_sum):
        nonlocal visited, best_objective, best_edges, best_signature
        nonlocal optimal_count, optimal_union, optimal_intersection, optimal_edge_union
        visited += 1
        if visited > max_nodes:
            raise RuntimeError("ranking enumeration budget exceeded; no partial final decision emitted")
        if best_objective is not None and len(selected_edges) + len(target_keys) - position < best_objective[0]:
            return
        if position == len(target_keys):
            objective = (len(selected_edges),) + rank_sum
            candidate_pairs = {(i, c) for i, t, c in selected_edges}
            stable = signature(selected_edges)
            if best_objective is None or objective > best_objective:
                best_objective, best_edges, best_signature = objective, list(selected_edges), stable
                optimal_count = 1
                optimal_union, optimal_intersection = set(candidate_pairs), set(candidate_pairs)
                optimal_edge_union = set(selected_edges)
            elif objective == best_objective:
                optimal_count += 1
                optimal_union |= candidate_pairs
                optimal_intersection &= candidate_pairs
                optimal_edge_union |= set(selected_edges)
                if stable < best_signature:
                    best_edges, best_signature = list(selected_edges), stable
            return
        i, t = target_keys[position]
        for c in options.get((i, t), []):
            # Known same-object targets cannot receive different report IDs.
            if any(old_i != i and old_c != c and
                   relations[(old_t, t) if i == 2 else (t, old_t)]["relation"] == "same_object"
                   for old_i, old_t, old_c in selected_edges):
                continue
            previous = used.get(c, [])
            if candidates[c]["object_scope"] == "single_object":
                if any(old_i == i for old_i, old_t in previous):
                    continue
                if previous:
                    old_i, old_t = previous[0]
                    if relations[(old_t, t) if i == 2 else (t, old_t)]["relation"] != "same_object":
                        continue
            used[c] = previous + [(i, t)]
            selected_edges.append((i, t, c))
            visit(position + 1, tuple(a + b for a, b in zip(rank_sum, ranks[(i, t, c)])))
            selected_edges.pop()
            if previous:
                used[c] = previous
            else:
                used.pop(c, None)
        visit(position + 1, rank_sum)

    visit(0, (0,) * len(RANK_ORDER))
    chosen_pairs = {(i, c) for i, t, c in best_edges}
    selected = {str(i): sorted({e for ii, c in chosen_pairs if ii == i for e in candidates[c]["entity_ids"]}, key=natural_id)
                for i in (1, 2)}
    rejected = {str(i): sorted({e for c, candidate in candidates.items() if (i, c) not in chosen_pairs for e in candidate["entity_ids"]}, key=natural_id)
                for i in (1, 2)}
    assignments = [{"image_index": i, "target_id": t, "candidate_key": c,
                    "entity_ids": candidates[c]["entity_ids"], "rank": list(ranks[(i, t, c)]),
                    "tie_break_selected": (i, c) not in optimal_intersection}
                   for i, t, c in sorted(best_edges)]
    return {
        "uid": payload["uid"], "method": "instance_round2_target_ranked_v3",
        "payload": payload, "model_output": output,
        "selected_instance_entities": selected,
        "rejected_instance_entities": rejected,
        "unresolved_instance_entities": {"1": [], "2": []},
        "matching_audit": {
            "canonical_target_ids": [{"image_index": i, "raw_id": old, "canonical_id": new} for (i, old), new in renamed.items()],
            "target_capacity": {str(i): len(targets[i]) for i in (1, 2)},
            "target_counts": {str(i): len(targets[i]) for i in (1, 2)},
            "maximum_covered_targets": best_objective[0],
            "selected_candidate_counts": {str(i): sum(ii == i for ii, c in chosen_pairs) for i in (1, 2)},
            "matched_target_counts": {str(i): sum(ii == i for ii, t, c in best_edges) for i in (1, 2)},
            "unmatched_targets": [{"image_index": i, "target_id": t} for i, t in target_keys if not any(ii == i and tt == t for ii, tt, c in best_edges)],
            "rank_order": ["covered_target_count"] + list(RANK_ORDER),
            "focal_feature_count_sources": ["differing_attributes", "candidate_known_attributes"]
            if any(image.get("candidate_known_attributes") for image in images.values()) else ["differing_attributes"],
            "best_objective": list(best_objective), "optimal_matching_count": optimal_count,
            "tie_break_rule": "lowest source entity IDs, then image index, then target ID; NOT identity proof",
            "tie_break_selected_candidate_pairs": sorted(chosen_pairs - optimal_intersection),
            "alternative_optimal_candidate_pairs": sorted(optimal_union),
            "alternative_optimal_target_edges": sorted(optimal_edge_union),
            "visited_nodes": visited, "enumeration_truncated": False,
            "target_assignments": assignments, "edge_decisions": edge_audit,
        },
    }

"""Report-only Instance equivalence for image-level family scoring.

Never treats family membership as physical identity or unknown as a wildcard.
Size is excluded because downstream size claims are permanently rejected.
"""
import hashlib
import json
from collections import defaultdict

from .instance_round2_target_contrast import equivalent_text
from .instance_round2_target_ranked import natural_id

POSITION_FIELDS = {"anatomic_region", "neck_level", "location_detail", "laterality", "source_laterality", "source_side", "region", "location", "position", "side"}
METADATA_FIELDS = {"instance_id", "entity_type", "identity_certainty", "instance_role", "extra_attributes", "size", "group_focal_detail"}
UNKNOWN = {"", "none", "unknown", "unspecified", "not specified", "null"}


def normalized(value):
    if value is None:
        return None
    if isinstance(value, (list, tuple)):
        values = [normalized(v) for v in value]
        return sorted((v for v in values if v is not None), key=lambda v: json.dumps(v, sort_keys=True)) or None
    if isinstance(value, dict):
        return {k: normalized(v) for k, v in sorted(value.items()) if normalized(v) is not None} or None
    return None if str(value).strip().lower() in UNKNOWN else equivalent_text(value)


def family_signature(instance, candidate):
    attributes = {k: normalized(v) for k, v in sorted(instance.items())
                  if k not in POSITION_FIELDS | METADATA_FIELDS and normalized(v) is not None}
    extras = set()
    for row in instance.get("extra_attributes", []):
        name = str(row.get("attribute_name", "")).strip().lower().replace(" ", "_")
        if not name or name in POSITION_FIELDS or name in {"size", "group_focal_detail"}:
            continue
        value = normalized(row.get("value"))
        if value is not None:
            extras.add(json.dumps([name, value], sort_keys=True, ensure_ascii=False))
    return {"entity_type": instance["entity_type"],
            "compartment": candidate["conditions"]["anatomy"],
            "object_scope": candidate["object_scope"],
            "nonposition_attributes": attributes,
            "nonposition_extra_attributes": [json.loads(v) for v in sorted(extras)]}


def build_instance_families(report, payload):
    instances = {i["instance_id"]: i for i in report.get("instances", [])}
    candidate_by_entity = {e: c for c in payload["instance_candidates"] for e in c["entity_ids"]}
    if set(instances) != set(candidate_by_entity):
        raise ValueError("Instance family universe differs from source report")
    groups, signatures = defaultdict(list), {}
    for entity, candidate in candidate_by_entity.items():
        signature = family_signature(instances[entity], candidate)
        rendered = json.dumps(signature, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
        family = "instance_family_" + hashlib.sha256((str(payload["uid"]) + "|" + rendered).encode()).hexdigest()[:16]
        groups[family].append(entity)
        signatures[family] = signature
    mapping = {e: f for f, members in groups.items() for e in members}
    families = [{"family_id": f, "entity_ids": sorted(members, key=natural_id), "signature": signatures[f]}
                for f, members in sorted(groups.items())]
    return {"uid": payload["uid"], "entity_to_family": mapping, "families": families}


def annotate_selected_families(result, family_data):
    """Keep canonical source IDs, distinguish family support from member identity.

    These are next-stage claim actions, NOT modifications of R1/gold claims.
    """
    mapping = family_data["entity_to_family"]
    candidate_map = {c["candidate_key"]: c for c in result["payload"]["instance_candidates"]}
    audit = result.get("matching_audit", {})
    pairs = {(int(p["image_index"]), p["target_id"], p["candidate_key"]): p
             for p in (result.get("model_output") or {}).get("pair_assessments", [])}
    tied = {tuple(p) for p in audit.get("tie_break_selected_candidate_pairs", [])}
    alternatives = [tuple(p) for p in audit.get("alternative_optimal_candidate_pairs", [])]
    target_alternatives = audit.get("alternative_optimal_target_edges")
    decisions = {"1": [], "2": []}
    for assignment in audit.get("target_assignments", []):
        i, t, c = assignment["image_index"], assignment["target_id"], assignment["candidate_key"]
        families = {mapping[e] for e in candidate_map[c]["entity_ids"]}
        other = ([(j, key) for j, target, key in target_alternatives if j == i and target == t and key != c]
                 if target_alternatives is not None else [(j, key) for j, key in alternatives if j == i and key != c])
        same_family_alternatives = [key for j, key in other
                                   if {mapping[e] for e in candidate_map[key]["entity_ids"]} == families]
        other_family_alternatives = [key for j, key in other
                                    if {mapping[e] for e in candidate_map[key]["entity_ids"]} != families]
        pair = pairs[(i, t, c)]
        conditions = candidate_map[c]["conditions"]
        specific_side_region = conditions.get("anatomic_region") in {"left_lobe", "right_lobe", "left_neck", "right_neck"}
        actions = {"source_laterality": "accept" if normalized(conditions.get("source_laterality")) is not None and pair["laterality_match"] == "yes" else "reject",
                   "anatomic_region": "accept" if normalized(conditions.get("anatomic_region")) is not None and pair["anatomic_region_match"] == "yes" and (not specific_side_region or pair["laterality_match"] == "yes") else "reject",
                   "neck_level": "accept" if normalized(conditions.get("neck_level")) is not None and pair["neck_level_match"] == "yes" else "reject",
                   "location_detail": "accept" if normalized(conditions.get("location_detail")) is not None and pair["location_detail_match"] == "yes" else "reject",
                   "size": "reject"}
        decisions[str(i)].append({"target_id": t, "candidate_key": c,
                                 "selected_family_ids": sorted(families),
                                 "selected_source_entity_ids": candidate_map[c]["entity_ids"],
                                 "selection_basis": "family_equivalent_tie" if (i, c) in tied and same_family_alternatives and not other_family_alternatives else "forced_tie" if (i, c) in tied else "ranked_match",
                                 "same_family_alternative_candidate_keys": sorted(same_family_alternatives),
                                 "other_family_alternative_candidate_keys": sorted(other_family_alternatives),
                                 "position_claim_actions": actions,
                                 "same_object_proven_by_family": False})
    result["instance_family_mapping"] = family_data
    result["selected_instance_families"] = {str(i): sorted({mapping[e] for e in result["selected_instance_entities"][str(i)]}) for i in (1, 2)}
    result["instance_family_decisions"] = decisions
    return result

"""Approved claim-only rules. No gold labels, images or network access."""
import math
import re

from .common import NONE

SIZE_RE = re.compile(r"_[23]DS_|<[^>]*size[^>]*>|\d+(?:\.\d+)?\s*(?:mm|cm)\b", re.I)
FLOW_RE = re.compile(r"\bCDFI\b|\bDoppler\b|blood\s*flow|vascularity|血流", re.I)
NON_VISUAL = {"examination_context", "examination_limitation", "examination_setting",
              "scanning_limitation", "patient_position", "patient_indicated_site",
              "patient_indicated_area", "result_limitation", "palpability"}


def values(card, field):
    axis = card.get(field, "unknown")
    raw = axis.get("values", [axis.get("value", "unknown")]) if isinstance(axis, dict) else axis
    raw = raw if isinstance(raw, (list, tuple, set)) else [raw]
    return {str(v) for v in raw if str(v or "").strip().lower() not in NONE}


def single(card, field):
    axis = card.get(field, "unknown")
    return str(axis.get("value", "unknown")) if isinstance(axis, dict) else str(axis)


def sides(value):
    text, result = str(value), set()
    if re.search(r"(?<![a-z])left(?![a-z])|左", text, re.I):
        result.add("left")
    if re.search(r"(?<![a-z])right(?![a-z])|右", text, re.I):
        result.add("right")
    if re.search(r"\bbilateral\b|\bboth\b|雙側|双侧", text, re.I):
        result.update(("left", "right"))
    if re.search(r"\bmidline\b|\bisthmus\b|中線|中线|峡部|峽部", text, re.I):
        result.add("midline")
    return result

REASONS = {
    "C01_SIZE_LIMIT": "dataset_measurement_evidence_incomplete",
    "C02_NO_DOPPLER": "doppler_required_for_flow_claim",
    "C03_LATERALITY_UNKNOWN": "image_laterality_unknown",
    "C04_SIDED_ANATOMY_UNKNOWN": "sided_region_requires_known_image_laterality",
    "C05_NECK_LEVEL_UNAVAILABLE": "neck_level_evidence_unavailable",
    "C06_NON_VISUAL_CONTEXT": "non_visual_context_attribute",
    "C07_ELASTOGRAPHY_REQUIRED": "elastography_image_required",
    "C08_ORIENTATION_PLANE": "orientation_requires_transverse_plane",
    "C16_ORIENTATION_UNCERTAIN_PLANE": "orientation_requires_trusted_plane",
    "C17_ORIENTATION_RATIO_PLACEHOLDER": "orientation_ratio_value_unavailable",
    "C18_POSTERIOR_ACOUSTIC_FEATURE": "posterior_acoustic_feature_excluded_by_project_policy",
}


def hits(claim, card, *, minimum_plane_confidence=.8, established_neck_level=False):
    attr, text = claim["attribute_name"], str(claim["value"])
    side_set = values(card, "laterality")
    vascular = attr in {"vascularity", "internal_vascularity", "peripheral_vascularity", "blood_flow"}
    vascular = vascular or (claim.get("source") == "extra_attribute" and bool(FLOW_RE.search(text)))
    conditions = {
        "C01_SIZE_LIMIT": (attr == "size" and claim["entity_kind"] == "instance") or
                          ((attr == "size" or attr.endswith("_size")) and bool(SIZE_RE.search(text))),
        "C02_NO_DOPPLER": vascular and single(card, "modality") != "color_doppler",
        "C03_LATERALITY_UNKNOWN": attr in {"laterality", "source_laterality"} and not side_set,
        "C04_SIDED_ANATOMY_UNKNOWN": attr == "anatomic_region" and bool(sides(text)) and not side_set,
        "C05_NECK_LEVEL_UNAVAILABLE": attr == "neck_level" and not established_neck_level,
        "C06_NON_VISUAL_CONTEXT": attr in NON_VISUAL,
        "C07_ELASTOGRAPHY_REQUIRED": "elastograph" in attr and single(card, "modality") != "elastography",
        "C08_ORIENTATION_PLANE": attr == "orientation" and single(card, "plane") != "transverse",
        # Explicit dataset policy, not a claim that the feature is never visible.
        "C18_POSTERIOR_ACOUSTIC_FEATURE": attr == "posterior_acoustic_feature",
    }
    result = [name for name, applies in conditions.items() if applies]
    if claim["attribute_name"] == "orientation":
        plane = card.get("plane", {})
        try:
            confidence = float(plane.get("confidence", 0)) if isinstance(plane, dict) else 0.
        except (TypeError, ValueError):
            confidence = 0.
        reviewed = isinstance(plane, dict) and plane.get("needs_review") is False
        if not math.isfinite(confidence) or confidence < minimum_plane_confidence or not reviewed:
            result.append("C16_ORIENTATION_UNCERTAIN_PLANE")
        if "_r_" in str(claim["value"]).lower():
            result.append("C17_ORIENTATION_RATIO_PLACEHOLDER")
    return result


def decide(claim, card, rule_ids, **kwargs):
    if set(rule_ids) - REASONS.keys():
        raise ValueError("Unsupported rules in approved profile")
    matching = set(hits(claim, card, **kwargs))
    applied = [r for r in rule_ids if r in matching]
    return {"decision": "reject" if applied else "defer", "rule_ids": applied,
            "reasons": [REASONS[r] for r in applied] or ["requires_visual_claim_grounding"]}

"""Claim expansion and upstream restrictions ported unchanged from main_code."""
from collections import Counter
import json
from .common import NONE

METADATA = {"region_id", "instance_id", "entity_type", "identity_certainty", "instance_role", "extra_attributes"}
POSITION = {"anatomic_region", "neck_level", "location_detail", "source_laterality", "laterality", "region", "site"}


def present(value):
    return value is not None and not (isinstance(value, str) and value.strip().lower() in NONE) and value not in ([], {})


def expand_claims(entity, kind, excluded_attributes=()):
    """Keep raw values; deduplicate exact attribute/value pairs like expert forms.

    Claim IDs match expert forms. No source_laterality skip. Review exclusions
    remain visible in a separate audit, with originals still in source entities.
    """
    entity_id = entity["region_id" if kind == "region" else "instance_id"]
    rows, excluded, seen, counts = [], [], set(), Counter()
    for name, value in entity.items():
        if name in METADATA or not present(value):
            continue
        if not isinstance(value, (str, int, float, bool)):
            raise ValueError(f"Unsupported compound direct attribute {entity_id}/{name}")
        row = {"claim_id": f"{entity_id}:{name}", "entity_id": entity_id, "entity_kind": kind,
               "entity_type": entity["entity_type"], "attribute_name": name, "value": value,
               "source": "routing_metadata" if name in {"anatomic_region", "neck_level"} else "direct",
               "source_pointer": f"/{name}"}
        seen.add((name, json.dumps(value, ensure_ascii=False, sort_keys=True)))
        (excluded if name in excluded_attributes else rows).append(row)
    for index, extra in enumerate(entity.get("extra_attributes", []) or []):
        if not isinstance(extra, dict):
            raise ValueError(f"Invalid extra attribute {entity_id}/{index}")
        name = str(extra.get("attribute_name", extra.get("name")) or "unnamed")
        value = extra.get("value")
        if not present(value):
            continue
        key = name, json.dumps(value, ensure_ascii=False, sort_keys=True)
        if key in seen:
            continue
        seen.add(key); counts[name] += 1
        row = {"claim_id": f"{entity_id}:extra:{name}:{counts[name]}", "entity_id": entity_id,
               "entity_kind": kind, "entity_type": entity["entity_type"], "attribute_name": name,
               "value": value, "source": "extra_attribute", "source_pointer": f"/extra_attributes/{index}/value"}
        (excluded if name in excluded_attributes else rows).append(row)
    return rows, excluded


def upstream_reject_reasons(image, claim):
    reasons = []
    if claim["entity_kind"] == "instance":
        for d in image.get("instance_family_decisions") or []:
            if claim["entity_id"] in d.get("selected_source_entity_ids", []):
                if d.get("position_claim_actions", {}).get(claim["attribute_name"]) == "reject":
                    reasons.append({"rule_id": "U02_ROUND2_CLAIM_REJECT", "reason": "preserve_round2_position_claim_action",
                                    "target_id": d.get("target_id"), "candidate_key": d.get("candidate_key")})
    elif claim["attribute_name"] in POSITION:
        for d in image.get("region_collapse_audit", []):
            if (int(d["image_index"]) == int(image["image_index"]) and
                d.get("member_resolution") == "unresolved_representative" and
                claim["entity_id"] in d.get("selected_members_after", [])):
                reasons.append({"rule_id": "U01_REGION_MEMBER_POSITION_UNRESOLVED",
                                "reason": "representative_id_does_not_establish_member_location",
                                "collapse_family_id": d.get("collapse_family_id")})
    return reasons

"""Split original combined position; preserve every non-position Round3 value."""
import copy

from ..round3.claims import present
from ..round3.prefilter import values


def components(raw, config):
    if not present(raw):
        return 'none', 'none'
    value = str(raw).strip().lower()
    if value not in config['mapping']:
        raise ValueError('Unsupported scalar anatomic_region: ' + value)
    return tuple(config['mapping'][value])


def decision(field, value, card, config):
    if value == 'none':
        return 'reject', 'P01', 'source_component_unspecified_or_not_applicable'
    prediction = values(card, 'anatomic_region' if field == 'anatomy' else 'laterality')
    required = config['card_anatomy'][value] if field == 'anatomy' else value
    if not prediction:
        return 'reject', 'P02' if field == 'anatomy' else 'P04', 'image_' + field + '_unknown'
    if required not in prediction:
        return 'reject', 'P03' if field == 'anatomy' else 'P05', 'image_' + field + '_conflict'
    return 'accept', 'P_COMPATIBLE', 'source_component_compatible_with_card'


def without_position(entity):
    return {k: v for k, v in entity.items() if k not in {'anatomic_region', 'anatomy', 'laterality'}}


def process_image(original_decisions, original_filtered, config):
    for key in ('uid', 'image_id', 'image_index'):
        if original_decisions[key] != original_filtered[key]:
            raise ValueError('Round3 identities differ')
    decisions, filtered = copy.deepcopy(original_decisions), copy.deepcopy(original_filtered)
    source, card = decisions['source_routing'], decisions['image_card']
    groups = {(g['entity_kind'], g['entity_id']): g for g in decisions['entity_claims']}
    audits = []
    for kind, collection, id_key in [('region', 'regions', 'region_id'), ('instance', 'instances', 'instance_id')]:
        if source[collection] is None:
            assert filtered[collection] is None
            continue
        outputs = {e[id_key]: e for e in filtered[collection]}
        for entity in source[collection]:
            entity_id = entity[id_key]
            if 'anatomy' in entity or 'laterality' in entity:
                raise ValueError('Input must be original combined-position schema')
            original_entity = copy.deepcopy(entity)
            final = outputs[entity_id]
            before = copy.deepcopy(final)
            group = groups[kind, entity_id]
            old_claims = [c for c in group['claims'] if c['attribute_name'] == 'anatomic_region' and c['source'] != 'extra_attribute']
            unchanged_claims = [c for c in group['claims'] if c not in old_claims]
            group['claims'] = unchanged_claims[:]
            raw = entity.pop('anatomic_region', 'none')
            final.pop('anatomic_region', None)
            anatomy, side = components(raw, config)
            new_claims = []
            for field, value in [('anatomy', anatomy), ('laterality', side)]:
                accept, rule, reason = decision(field, value, card, config)
                if anatomy == 'isthmus' and field == 'laterality':
                    rule, reason = 'P06', 'isthmus_has_no_left_right_component'
                entity[field] = value
                final[field] = value if accept == 'accept' else 'none'
                claim = {'claim_id': entity_id + ':' + field, 'entity_id': entity_id,
                         'entity_kind': kind, 'entity_type': entity['entity_type'],
                         'attribute_name': field, 'value': value, 'source': 'routing_metadata',
                         'source_pointer': '/' + field, 'decision': accept, 'rule_ids': [rule],
                         'reasons': [reason], 'decision_basis': config['version'], 'upstream_evidence': []}
                group['claims'].append(claim)
                new_claims.append(claim)
            assert without_position(before) == without_position(final)
            assert without_position(original_entity) == without_position(entity)
            assert [c for c in group['claims'] if c['attribute_name'] not in {'anatomy', 'laterality'}] == unchanged_claims
            audits.append({'uid': str(filtered['uid']), 'image_id': filtered['image_id'], 'image_index': filtered['image_index'],
                           'entity_kind': kind, 'entity_id': entity_id, 'entity_type': entity['entity_type'],
                           'original_anatomic_region': raw, 'original_combined_claims': old_claims,
                           'component_claims': new_claims,
                           'image_card_anatomy': sorted(values(card, 'anatomic_region')),
                           'image_card_laterality': sorted(values(card, 'laterality'))})
    decisions['position_split_policy'] = filtered['position_split_policy'] = config['version']
    decisions['counts'] = {d: sum(c['decision'] == d for g in decisions['entity_claims'] for c in g['claims']) for d in ('accept', 'reject')}
    return decisions, filtered, audits

"""Conservative lexical normalization and exact full-attribute Region signatures."""
import copy
import hashlib
import json
import re

from ..round3.claims import POSITION as LEGACY_POSITION, present

POSITION = LEGACY_POSITION | {"anatomy"}


def strip_sides(value, config):
    if not isinstance(value, str) or not present(value):
        return value, []
    original = value
    changes = []
    # Avoid interpreting geometric right-angle wording as patient laterality.
    words = "|".join(re.escape(w) for w in config["side_words"] if w != "right")
    pattern = re.compile(r"\b(?:" + words + r")\b|\bright\b(?![-\s]+angl)", re.I)
    chinese = re.compile("|".join(re.escape(w) for w in config["chinese_side_words"]))
    both = re.compile(r"\bboth\b(?=\s+(?:thyroid\s+)?(?:lobes|sides)\b)", re.I)
    for regex in (pattern, chinese, both):
        def delete(match):
            changes.append({"word": match.group(0), "start_in_current_pass": match.start()})
            return ""
        value = regex.sub(delete, value)
    if not changes:
        return original, []
    return " ".join(value.split()) or config["none_value"], changes


def raw_clause(text):
    return " ".join(str(text).casefold().split()).strip(" .;。；")


def clauses(value):
    if not isinstance(value, str):
        return [json.dumps(value, sort_keys=True, ensure_ascii=False)]
    # Do not split a decimal number such as 1.2 or erase qualifiers/conjunctions.
    return [p.strip() for p in re.split(r"(?<=[.!?。])\s+(?=[A-Za-z])|[;；]\s*", value) if p.strip()]


def clause_key(field, value, config):
    normalized = raw_clause(value)
    for index, synonyms in enumerate(config["aliases"].get(field, [])):
        if normalized in {raw_clause(s) for s in synonyms}:
            return f"@alias:{field}:{index}"
    return normalized


def value_key(field, value, config):
    if not present(value):
        return ("none",)
    return tuple(sorted(set(clause_key(field, part, config) for part in clauses(value))))


def dedup_clauses(field, value, config):
    if not isinstance(value, str) or not present(value):
        return value
    parts = clauses(value)
    kept, seen = [], set()
    for part in parts:
        key = clause_key(field, part, config)
        if key not in seen:
            kept.append(part)
            seen.add(key)
    # Preserve original punctuation/layout unless an actual repeated clause was removed.
    return value if len(kept) == len(parts) else " ".join(kept)


def normalize_region(entity, group, config):
    if entity["entity_type"] not in config["core_fields"]:
        raise ValueError("Unsupported Region entity_type")
    result = {k: copy.deepcopy(v) for k, v in entity.items() if k != "extra_attributes"}
    for field in config["core_fields"][entity["entity_type"]]:
        result.setdefault(field, config["none_value"])
    trace = []
    # Original values are retained in the audit; reject itself is not a wildcard.
    for claim in group["claims"]:
        if claim["source"] != "extra_attribute":
            result[claim["attribute_name"]] = copy.deepcopy(claim["value"]) if claim["decision"] == "accept" else config["none_value"]
    for field in list(result):
        if field in {"region_id", "entity_type"}:
            continue
        if not present(result[field]):
            result[field] = config["none_value"]
        elif field not in POSITION:
            original = result[field]
            result[field], removed = strip_sides(result[field], config)
            result[field] = dedup_clauses(field, result[field], config)
            if removed or result[field] != original:
                trace.append({"field": field, "original": original, "normalized": result[field], "removed_words": removed})
    extras = []
    seen = set()
    for claim in group["claims"]:
        if claim["source"] != "extra_attribute":
            continue
        name = claim["attribute_name"]
        value = copy.deepcopy(claim["value"]) if claim["decision"] == "accept" else config["none_value"]
        if not present(value):
            value = config["none_value"]
        elif name not in POSITION:
            original = value
            value, removed = strip_sides(value, config)
            value = dedup_clauses(name, value, config)
            if removed or value != original:
                trace.append({"field": f"extra:{name}", "source_pointer": claim["source_pointer"],
                              "original": original, "normalized": value, "removed_words": removed})
        key = name, value_key(name, value, config)
        if key not in seen:
            extras.append({"attribute_name": name, "value": value})
            seen.add(key)
    result["extra_attributes"] = extras
    return result, trace


def region_signature(region, config):
    # Absent and explicit none both represent no available value. Neither equals known.
    fields = set(region) - {"region_id", "entity_type", "extra_attributes"}
    fields |= set(config["core_fields"][region["entity_type"]])
    direct = {k: value_key(k, region.get(k), config) for k in sorted(fields)
              if present(region.get(k))}
    extra = sorted({(e["attribute_name"], value_key(e["attribute_name"], e.get("value"), config))
                    for e in region.get("extra_attributes", []) if present(e.get("value"))})
    return json.dumps({"entity_type": region["entity_type"], "direct": direct, "extras": extra},
                      sort_keys=True, ensure_ascii=False)


def equivalence_id(signature):
    return "region_equivalence_" + hashlib.sha256(signature.encode()).hexdigest()[:16]


def merge_regions(entries, config, *, case_level=False):
    """Each entry is (Region, source bindings). No union or nearest-neighbor matching."""
    groups = {}
    for entity, sources in entries:
        signature = region_signature(entity, config)
        if signature not in groups:
            groups[signature] = {"region": copy.deepcopy(entity), "sources": [], "input_members": 0,
                                 "equivalence_id": equivalence_id(signature)}
        groups[signature]["input_members"] += 1
        groups[signature]["sources"].extend(copy.deepcopy(sources))
    result, mapping = [], []
    for index, (signature, group) in enumerate(groups.items(), 1):
        region = group["region"]
        if case_level:
            region["region_id"] = f"region_{index}"
        # Every other field must already be equivalent; never fill a none or union values.
        assert region_signature(region, config) == signature
        result.append(region)
        mapping.append({"region_id": region["region_id"], "equivalence_id": group["equivalence_id"],
                        "sources": group["sources"], "input_members": group["input_members"]})
    return result, mapping
